return ['domain'=>'tag-groups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl-NL','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-17 15:08+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Tag-Groups stelt je in staat om je WordPress taxonomy termen te organiseren en ze weer te geven in wolken, tabbladen, accordeons, tabellen, lijsten en nog veel meer.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Home','Taxonomies'=>'Taxonomies','Front End'=>'Front End','Back End'=>'Back End','First Steps'=>'Eerste Stappen','Setup Wizard'=>'Installatie Wizard','Settings'=>'Instellingen','Tag Group Admin'=>'Tag Groep Admin','The term has been removed from all groups.'=>'De term is uit alle groepen verwijderd.','Edit this item inline'=>'Bewerk dit item inline','Quick&nbsp;Edit'=>'Snelle&nbsp;Bewerking','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Klik <a %s>hier om de migratieroutines uit te voeren</a> om er zeker van te zijn dat we alle tags hebben gemigreerd.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Je instellingen/groepen en je termen zijn geëxporteerd. Download de resulterende bestanden met rechtsklikken of ctrl-klik:','Writing of the exported settings failed.'=>'Het schrijven van de geëxporteerde instellingen is mislukt.','The groups have been sorted alphabetically.'=>'De groepen zijn alfabetisch gesorteerd.','The label cannot be empty.'=>'Het label kan niet leeg zijn.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose